import { create } from 'zustand'
import * as Sentry from '@sentry/react'
import { fetchWithRetry, parseJsonHeader } from '@/api/client'

interface TerrainMeshData {
  positions: Float32Array
  indices: Uint32Array
  width: number
  height: number
  hasElevation: boolean
  elevationRangeM: number
}

interface TerrainState {
  enabled: boolean
  meshData: TerrainMeshData | null
  loading: boolean
  error: string | null
  setEnabled: (v: boolean) => void
  fetchTerrain: (lat: number, lon: number, radius: number) => Promise<void>
}

function parseTerrainBinary(
  buf: ArrayBuffer,
  meta: Record<string, unknown>,
): TerrainMeshData {
  const nV = meta.n_vertices as number
  const nT = meta.n_triangles as number

  if (!Number.isFinite(nV) || !Number.isFinite(nT) || nV < 0 || nT < 0) {
    throw new Error(`Invalid terrain mesh metadata: n_vertices=${nV}, n_triangles=${nT}`)
  }

  const expectedBytes = nV * 3 * 4 + nT * 3 * 4
  if (buf.byteLength < expectedBytes) {
    throw new Error(
      `Terrain mesh buffer too small: got ${buf.byteLength} bytes, expected ${expectedBytes} ` +
      `(${nV} vertices, ${nT} triangles)`
    )
  }

  let offset = 0

  const positions = new Float32Array(buf, offset, nV * 3)
  offset += nV * 3 * 4

  const indices = new Uint32Array(buf, offset, nT * 3)

  return {
    positions,
    indices,
    width: meta.width as number,
    height: meta.height as number,
    hasElevation: (meta.has_elevation as boolean) ?? false,
    elevationRangeM: (meta.elevation_range_m as number) ?? 0,
  }
}

export const useTerrainStore = create<TerrainState>((set) => ({
  enabled: false,
  meshData: null,
  loading: false,
  error: null,

  setEnabled: (enabled) => set({ enabled }),

  fetchTerrain: async (lat, lon, radius) => {
    set({ loading: true, error: null })
    try {
      const resp = await fetchWithRetry('/api/terrain/elevation', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ lat, lon, radius }),
      })
      if (!resp.ok) {
        let msg = `HTTP ${resp.status}`
        try { const err = await resp.json(); msg = (err as { error?: string }).error || msg } catch {}
        throw new Error(msg)
      }
      const meta = parseJsonHeader<Record<string, unknown>>(resp.headers.get('X-Meta'), 'X-Meta')
      const buf = await resp.arrayBuffer()
      const meshData = parseTerrainBinary(buf, meta)
      set({ meshData, loading: false, enabled: true })
    } catch (e) {
      Sentry.captureException(e)
      set({ error: (e as Error).message, loading: false })
    }
  },
}))
